# The following code was partially generated by Claude AI https://claude.ai
def generate_track_middlepoints() -> List[Tuple[int,int]]:
    """
    Generates a list of all points in the middle of the track.
    :returns: List of tuples representing points (x,y) in the middle of the track
    """ 
    break_points = create_pathline()
    out = []
    # Process each segment between consecutive break points
    for i in range(len(break_points) - 1):
        x1, y1 = break_points[i]
        x2, y2 = break_points[i + 1]
        
        # Horizontal segment
        if y1 == y2:
            start_x, end_x = min(x1, x2), max(x1, x2)
            for x in range(start_x, end_x + 1):
                out.append((x, y1))
        
        # Vertical segment
        elif x1 == x2:
            start_y, end_y = min(y1, y2), max(y1, y2)
            for y in range(start_y, end_y + 1):
                out.append((x1, y))

    return out


def generate_all_points_on_track(modulo: int = 1, extended_by: int = 0) -> List[Tuple[int,int]]:
    """
    Generates a list of all points on the the track.
    :param modulo: if both point coordinates are divisible by modulo, it will be kept; approximately
    1/(modulo^2) points will be kept
    :param extended_by: by how much to increase or shrink the width of resulting lines; should be at 
    most -19
    :returns: List of tuples representing points (x,y) on the track
    """

    out_set = set()
    break_points = create_pathline()
    track_middle_points = generate_track_middlepoints()
    
    # Add points for the first middlepoint:
    for y_add in range(- 20 - extended_by, 21 + extended_by):
         # Filter for divisibility
           if is_point_modulo((-40, 230+y_add), modulo):
               out_set.add((-40, 230+y_add))

    # Add all other points, except for cornerpoints
    for i in range(1, len(track_middle_points), 1):
        x1 = track_middle_points[i-1][0]
        x2 = track_middle_points[i][0]
        y1 = track_middle_points[i-1][1]
        y2 = track_middle_points[i][1]

        # Horizontal segment
        if y1 == y2:
            for y_add in range(-20 - extended_by, 21 + extended_by):
               # Filter for divisibility
               if is_point_modulo((x2, y2+y_add), modulo):
                   out_set.add((x2, y2+y_add))
        
        # Vertical segment
        elif x1 == x2:
            for x_add in range(-20 - extended_by, 21 + extended_by):
                # Filter for divisibility
                if is_point_modulo((x2+x_add, y2), modulo):
                    out_set.add((x2+x_add, y2))
    
    # Add points around the corners of the track
    for i in range(1, len(break_points)-1, 1):
        points_in_square = generate_square_integer_points(break_points[i], 20 + extended_by)
        for x,y in points_in_square:
           # Filter for divisibility
           if is_point_modulo((x,y), modulo):
               out_set.add((x,y))    

    # Make into a list and output   
    out = list(out_set)  

    return out
        
def generate_footprint_constraint_set(pos: Tuple[int,int], modulo: int = 1) -> List[Tuple[int,int]]:
    """
    Generates a set of points in which no tower can be placed given than there is already a tower placed at
    pos.
    :param pos: position in relation to which the set is computed
    :param modulo: if both point coordinates are divisible by modulo, it will be kept; approximately
    1/(modulo^2) points will be kept
    :returns: List of tuples representing points (x,y) in which no tower can be built, given that
    a tower is built at pos
    """
    out = []
    DART_MONKEY_FOOTPRINT = 10
    zone_radius = DART_MONKEY_FOOTPRINT*2 # Needed as footprints cannot coincide
    zone_circle = Circle(zone_radius, pos)
    min_x = pos[0] - zone_radius
    max_x = pos[0] + zone_radius
    min_y = pos[1] - zone_radius
    max_y = pos[1] + zone_radius

    for x in range(min_x, max_x+1):
        for y in range(min_y, max_y+1):
            # Check if it is in circle and filter for divisibility
            if is_point_in_circle(zone_circle, x, y) and is_point_modulo((x,y), modulo):
                out.append((x,y))
    
    return out


def generate_all_tower_placements(modulo: int = 1, super_monkey: bool = False) -> List[Tuple[int, int]]: 
    """
    Generates a set of points in which towers can be placed
    :param modulo: if both point coordinates are divisible by modulo, it will be kept; approximately
    1/(modulo^2) points will be kept
    :returns: List of tuples representing points (x,y) in which towers can be places
    """
    if super_monkey:
        radius = 15
    else:
        radius = 10

    not_outside_set = set()
    for x in range(radius,481 - radius):
        for y in range(radius, 481 - radius):
            # Filter for divisibility
            if is_point_modulo((x,y), modulo):
                not_outside_set.add((x,y))  
    
    too_close_to_track_set = set(generate_all_points_on_track(modulo, radius))

    out = list(not_outside_set - too_close_to_track_set)
    return out

   
def generate_coverage_dict(modulo: int = 1) -> Dict[Tuple[int,int], int]:
    out = {}
    DART_MONKEY_RANGE = 100

    rad = DART_MONKEY_RANGE
    tower_placements = generate_all_tower_placements(modulo)
    midpoints = generate_track_middlepoints()

    for i in range(len(tower_placements)):
        var = tower_placements[i]
        circle = Circle(rad, var)
        counter = 0
        for p in midpoints:
            if is_point_in_circle(circle, p[0], p[1]):
                counter += 1
        out[var] = counter
    return out


def generate_all_footprint_constraint_sets(modulo: int = 1, adjust: bool = True) -> Dict[Tuple[int,int], List[Tuple[int,int]]]:
    """
    Generates all footprint constaint sets.
    :param modulo: if both point coordinates are divisible by modulo, it will be kept; approximately
    1/(modulo^2) points will be kept
    :param adjust: whether to substract points that are not in all possible tower positions from the 
    resulting set (True) or not (False)
    """
    out = {}
    tower_placements = generate_all_tower_placements(modulo)
    # Set for quick inclusion check
    if adjust:
        tower_placement_set = set(tower_placements)

    for i in range(len(tower_placements)):
        var = tower_placements[i]
        out[var] = []
        footprint_points =  generate_footprint_constraint_set(var, modulo)
        
        if adjust:
            # Disregard values than cannot be chosen for tower placement either way
            for point in footprint_points:
                if point in tower_placement_set:
                    out[var].append(point)

        else:
            out[var].append(point)

    return out


def get_money_constraint_rhs() -> int:
    """
    Determines the amount of money the player will have based on the
    proportion of pops achieved.
    """
    total_money = 650 # Starting amount
    rounds_info = create_rounds_dataframe()

    round_end_money = rounds_info['money_round_end'].sum()
    total_money += round_end_money 


    max_RBE = rounds_info['RBE_Cash'].sum()
    # We cannot afford to leave more than 39 RBE unpopped (we have 40 lives total)
    pop_money_worst_case = max_RBE-39
    total_money += pop_money_worst_case

    return math.floor(total_money)


